struct cake {
    int a, b;
    bool owner; 
    int id;     
    bool operator <(const cake& other) const {
        assert(owner == other.owner);
        return (owner ? a : b) < (other.owner ? other.a : other.b);
    }
};

struct state {
    cake cur;
    int d;
};

const int maxn = 1e5 + 5;
int n;
long long d;
cake a[maxn], b[maxn];
int dist[maxn][2]; 

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> d;
    for(int i = 1; i <= n; i++) {
        cin >> a[i].a >> a[i].b;
        a[i].owner = 1;
        a[i].id = i;
    }
    for(int i = 1; i <= n; i++) {
        cin >> b[i].a >> b[i].b;
        b[i].owner = 0;
        b[i].id = i;
    }

    for(int i = 1; i <= n; i++) dist[i][0] = dist[i][1] = -1;

    queue<pair<int,int>> q; 

    for(int i = 1; i <= n; i++){
        if(a[i].b == 0) { dist[i][1] = 1; q.push({i,1}); }
        if(b[i].a == 0) { dist[i][0] = 1; q.push({i,0}); }
    }

    set<pair<int,int>> by_a, by_b;
    for(int i = 1; i <= n; i++) by_a.insert({b[i].a, i});
    for(int i = 1; i <= n; i++) by_b.insert({a[i].b, i});

    while(!q.empty()){
        auto [idx, owner] = q.front(); q.pop();

        if(owner == 1){
            long long low = (long long)a[idx].a - d;
            if(low < 0) low = 0;
            auto it = by_a.lower_bound({(int)low, -1});
            while(it != by_a.end() && it->first <= a[idx].a){
                int id_next = it->second;
                auto it2 = it++;
                by_a.erase(it2);
                if(dist[id_next][0] == -1){
                    dist[id_next][0] = dist[idx][1] + 1;
                    q.push({id_next,0});
                }
            }
        } else {

            long long low = (long long)b[idx].b - d;
            if(low < 0) low = 0;
            auto it = by_b.lower_bound({(int)low, -1});
            while(it != by_b.end() && it->first <= b[idx].b){
                int id_next = it->second;
                auto it2 = it++;
                by_b.erase(it2);
                if(dist[id_next][1] == -1){
                    dist[id_next][1] = dist[idx][0] + 1;
                    q.push({id_next,1});
                }
            }
        }
    }

    for(int i = 1; i <= n; i++){
        cout << dist[i][1] << "\n"; 
    }
}